test('Admin: add member with validation, manage access, audit export, activity chart/table/filter',async()=>{const user=userEvent.setup();render(<App/>);await settleGrid();await actor(user,'Admin');assert.equal(screen.queryByRole('button',{name:'System'}),null);await user.click(screen.getByRole('tab',{name:'Table'}));await settleGrid();assert.equal(document.querySelectorAll('[role="row"][row-id]').length,12);await select(user,'Activity wiki','Arabic');await user.click(screen.getByRole('button',{name:'Members'}));await user.click(screen.getByRole('button',{name:'Add member'}));let d=screen.getByRole('dialog');await user.click(within(d).getByRole('button',{name:'Create member'}));assert.ok(within(d).getByRole('alert'));await user.type(within(d).getByRole('textbox',{name:'Full name'}),'Maya Chen');await user.type(within(d).getByRole('textbox',{name:'Email address'}),'maya@example.org');await user.click(within(d).getByRole('button',{name:'Create member'}));assert.ok(screen.getByText('Maya Chen'));await user.click(screen.getByRole('button',{name:'Manage Maya Chen'}));d=screen.getByRole('dialog');await user.click(within(d).getByRole('checkbox',{name:'Active workspace access'}));await user.click(within(d).getByRole('button',{name:'Save member'}));const row=screen.getAllByRole('row').find(r=>r.textContent?.includes('Maya Chen'))!;assert.ok(within(row).getByText('Inactive'));await user.click(screen.getByRole('button',{name:'Audit Log'}));await select(user,'Audit action','Added member');assert.ok(screen.getByText('Maya Chen'));let captured:any;let downloaded='';const oldCreate=URL.createObjectURL,oldRevoke=URL.revokeObjectURL;URL.createObjectURL=(blob:any)=>{captured=blob;return 'blob:demo'};URL.revokeObjectURL=()=>{};const oldClick=dom.window.HTMLAnchorElement.prototype.click;dom.window.HTMLAnchorElement.prototype.click=function(){downloaded=this.download};await user.click(screen.getByRole('button',{name:'Export CSV'}));assert.equal(downloaded,'patrol-audit-log.csv');assert.match(await captured.text(),/Added member/);assert.doesNotMatch(await captured.text(),/Deactivated member/);URL.createObjectURL=oldCreate;URL.revokeObjectURL=oldRevoke;dom.window.HTMLAnchorElement.prototype.click=oldClick;});

