test('Selection menu supports keyboard, Escape and leaves ordinary right-click untouched',async()=>{const user=userEvent.setup();render(<App/>);await settleGrid();await openFirst(user);assert.equal(baseScreen.queryByRole('button',{name:'Comment on selection'}),null);const file=document.getElementById('file-rev-10000')!;const text=file.querySelector('[data-side="new"][data-source-start="15"]')||file.querySelector('[data-side="new"]')!;window.getSelection()!.removeAllRanges();assert.ok(fireEvent.contextMenu(text,{clientX:30,clientY:40}));assert.equal(within(file).queryByRole('menu'),null);const range=document.createRange();range.selectNodeContents(text);const viewport=within(file).getByLabelText('Revision differences');viewport.focus();range.selectNodeContents(text);window.getSelection()!.removeAllRanges();window.getSelection()!.addRange(range);fireEvent.keyDown(viewport,{key:'F10',shiftKey:true});assert.ok(within(file).getByRole('menu',{name:'Selected text actions'}));await user.keyboard('{Escape}');assert.equal(within(file).queryByRole('menu'),null);assert.equal(document.activeElement,viewport);range.selectNodeContents(text);window.getSelection()!.removeAllRanges();window.getSelection()!.addRange(range);fireEvent.keyDown(viewport,{key:'ContextMenu'});await user.click(within(file).getByRole('menuitem',{name:'Add comment'}));assert.ok(within(file).getByTestId('inline-composer'));assert.equal(document.activeElement,within(file).getByLabelText('Comment',{exact:true}));});

