test('Follow live uses a three-second schedule and holds during row interaction or older-page browsing',async()=>{const {Feed}=await import('../src/App');const {act}=await import('@testing-library/react');const originalSet=globalThis.setInterval,originalClear=globalThis.clearInterval;let tick:(()=>void)|undefined;globalThis.setInterval=((fn:any,ms:any,...args:any[])=>{if(ms===3000){tick=fn;return 700001}return originalSet(fn,ms,...args)}) as any;globalThis.clearInterval=((id:any)=>{if(id===700001){tick=undefined;return}originalClear(id)}) as any;try{const user=userEvent.setup();const initial=seed();const props={role:'lead' as const,actor:'sara',act:()=>true,offline:false,onOpen:()=>{},mode:'wiki'};const view=render(<Feed {...props} store={initial}/>);await settleGrid();await user.click(baseScreen.getByRole('button',{name:'Follow live'}));assert.ok(tick);const incoming={...initial,arrivals:1,edits:[{...initial.edits[0],id:'fresh-1',title:'Fresh edit'},...initial.edits]};view.rerender(<Feed {...props} store={incoming}/>);await settleGrid();assert.ok(baseScreen.queryByText('Fresh edit')===null);await act(()=>tick!());assert.ok(baseScreen.queryByText('Fresh edit')===null);Object.defineProperty(document,'hidden',{value:false,configurable:true});await act(()=>tick!());assert.ok(baseScreen.getByText('Fresh edit'));await user.hover(baseScreen.getByRole('grid'));assert.ok(!tick);await user.unhover(baseScreen.getByRole('grid'));assert.ok(tick);await user.click(baseScreen.getByRole('button',{name:'Next page'}));assert.ok(!tick);await user.click(baseScreen.getByRole('button',{name:'Previous page'}));assert.ok(!tick);await user.click(baseScreen.getByRole('textbox',{name:'Search live feed'}));assert.ok(tick);await user.click(baseScreen.getByRole('button',{name:'Stop following'}));assert.ok(!tick)}finally{cleanup();delete (document as any).hidden;globalThis.setInterval=originalSet;globalThis.clearInterval=originalClear}});


