test('Startup and gap intervals retain observed edits and chart bars',async()=>{const {activityData}=await import('../src/activity');const {ActivityChart}=await import('../src/Charts');const now=Date.parse('2026-10-08T13:15:25Z'),s=seed();s.edits=[];s.observationStart=Date.parse('2026-10-08T13:13:16Z');s.observations=[{key:'a',wiki:'en',title:'A',time:Date.parse('2026-10-08T13:13:00Z'),count:30},{key:'b',wiki:'ar',title:'B',time:Date.parse('2026-10-08T13:14:00Z'),count:40},{key:'c',wiki:'ja',title:'C',time:Date.parse('2026-10-08T13:15:00Z'),count:34}];s.gaps=[{start:Date.parse('2026-10-08T13:14:10Z'),end:Date.parse('2026-10-08T13:14:35Z')}];const data=activityData(s,60,true,now);assert.equal(data.total,104);assert.equal(data.bins.length,3);assert.deepEqual(data.bins.map(b=>b.count),[30,40,34]);assert.ok(data.bins.every(b=>b.partial));assert.equal(data.coveredSeconds,104);const original=HTMLElement.prototype.getBoundingClientRect;HTMLElement.prototype.getBoundingClientRect=function(){if(this.classList.contains('recharts-responsive-container'))return {width:760,height:255,top:0,left:0,right:760,bottom:255,x:0,y:0,toJSON:()=>({})} as DOMRect;return original.call(this)};try{render(<ActivityChart bins={data.bins}/>);await settleGrid();assert.ok(document.querySelectorAll('.recharts-bar-rectangle path').length>0);const user=userEvent.setup();await user.click(baseScreen.getByRole('button',{name:'English 30'}));assert.equal(baseScreen.getByRole('button',{name:'English 30'}).getAttribute('aria-pressed'),'false')}finally{HTMLElement.prototype.getBoundingClientRect=original}});

test('Dev mode is isolated and actual stream reconnect and browser network lifecycle work',async()=>{const originalFetch=globalThis.fetch,originalSource=(globalThis as any).EventSource;const instances:any[]=[];class TestSource{onopen:any;onerror:any;onmessage:any;closed=false;constructor(public url:string){instances.push(this)}close(){this.closed=true}}globalThis.fetch=(async()=>({ok:true,json:async()=>({query:{recentchanges:[]}})})) as any;(globalThis as any).EventSource=TestSource;localStorage.setItem('patrol-source','wiki');try{const user=userEvent.setup();render(<App/>);await settleGrid();assert.equal(instances.length,1);assert.ok(baseScreen.queryByRole('button',{name:'Simulate disconnect'})===null);assert.ok(baseScreen.queryByText(/^Wikimedia:/)===null);await act(()=>instances[0].onopen());await user.click(baseScreen.getByRole('button',{name:'Dev mode'}));let dialog=baseScreen.getByRole('dialog',{name:'Dev mode'});assert.ok(within(dialog).getByText('Wikimedia: Connected'));await user.click(within(dialog).getByRole('button',{name:'Reconnect stream'}));assert.equal(instances.length,2);assert.equal(instances[0].closed,true);await user.keyboard('{Escape}');assert.equal(instances.length,2);assert.equal(instances[1].closed,false);await act(()=>window.dispatchEvent(new Event('offline')));assert.equal(instances[1].closed,true);assert.ok(baseScreen.getByText(/Browser offline\. Saved reviews/));await act(()=>window.dispatchEvent(new Event('online')));assert.equal(instances.length,3);assert.ok(baseScreen.queryByText(/Browser offline\. Saved reviews/)===null);await act(()=>instances[2].onerror());await user.click(baseScreen.getByRole('button',{name:'Dev mode'}));dialog=baseScreen.getByRole('dialog',{name:'Dev mode'});assert.ok(within(dialog).getByText('Wikimedia: Reconnecting'))}finally{cleanup();globalThis.fetch=originalFetch;(globalThis as any).EventSource=originalSource}});

test('Grid selection stays checked, is duplicate-safe, and select all targets the filtered sorted current page',async()=>{const {Feed}=await import('../src/App');const user=userEvent.setup();const initial=seed();initial.edits=Array.from({length:30},(_,i)=>({...initial.edits[0],id:`select-${i}`,title:`Selection ${i}`,delta:i}));let batch:string[]=[];const props={role:'patroller' as const,actor:'dev',act:()=>true,offline:false,onOpen:(_edit:any,ids?:string[])=>{batch=ids||[]},mode:'wiki'};const view=render(<Feed {...props} store={initial}/>);await settleGrid();const header=()=>baseScreen.getByRole('checkbox',{name:'Select all edits on current page'}) as HTMLInputElement;const count=(n:number)=>baseScreen.getByRole('button',{name:`Review selected (${n})`});for(let i=0;i<4;i++){await user.click(rowCheckbox('select-0'));assert.equal(rowCheckbox('select-0').checked,true);assert.ok(count(1));view.rerender(<Feed {...props} store={{...initial,arrivals:i+1}}/>);await settleGrid();assert.equal(rowCheckbox('select-0').checked,true);await user.click(rowCheckbox('select-0'));assert.equal(rowCheckbox('select-0').checked,false);assert.ok(count(0))}rowCheckbox('select-0').focus();await user.keyboard(' ');assert.equal(rowCheckbox('select-0').checked,true);assert.ok(count(1));await user.click(header());assert.ok(count(12));assert.equal(header().checked,true);for(let i=0;i<12;i++)assert.equal(rowCheckbox(`select-${i}`).checked,true);await user.click(rowCheckbox('select-0'));assert.ok(count(11));assert.equal(header().indeterminate,true);await user.click(baseScreen.getByRole('button',{name:'Next page'}));await settleGrid();assert.equal(header().checked,false);await user.click(header());assert.ok(count(23));for(let i=12;i<24;i++)assert.equal(rowCheckbox(`select-${i}`).checked,true);await user.click(header());assert.ok(count(11));await user.click(baseScreen.getByRole('button',{name:'Previous page'}));await settleGrid();assert.equal(rowCheckbox('select-0').checked,false);assert.equal(rowCheckbox('select-1').checked,true);await user.click(header());assert.ok(count(12));await user.click(header());assert.ok(count(0));const filter=await openGridFilter(user,'3');await user.type(filter,'27');await waitFor(()=>assert.ok(baseScreen.getByRole('button',{name:'Inspect Selection 27'})));await user.keyboard('{Escape}');await user.click(header());assert.ok(count(1));assert.equal(rowCheckbox('select-27').checked,true);await user.click(baseScreen.getByRole('button',{name:'Clear filters'}));await waitFor(()=>assert.ok(baseScreen.getByRole('button',{name:'Inspect Selection 0'})));baseScreen.getByRole('columnheader',{name:'Change',exact:true}).focus();await user.keyboard('{Enter}{Enter}');await waitFor(()=>assert.ok(baseScreen.getByRole('button',{name:'Inspect Selection 29'})));assert.equal(rowCheckbox('select-27').checked,true);await user.click(header());assert.ok(count(12));for(let i=18;i<30;i++)assert.equal(rowCheckbox(`select-${i}`).checked,true);await user.click(count(12));assert.equal(batch.length,12);assert.equal(new Set(batch).size,12);assert.deepEqual(new Set(batch),new Set(Array.from({length:12},(_,i)=>`select-${18+i}`)))});

test('WikiWatch puts batch review in the feed header with keyboard-accessible help',async()=>{const user=userEvent.setup();render(<App/>);await settleGrid();assert.ok(baseScreen.getByRole('link',{name:'WikiWatch home'}));const header=baseScreen.getByLabelText('Recent edits header');assert.ok((within(header).getByRole('button',{name:'Review selected (0)'}) as HTMLButtonElement).disabled);assert.equal(baseScreen.queryByText('Each selected revision is reviewed separately.'),null);await user.click(rowCheckbox('rev-10000'));assert.ok(within(header).getByRole('button',{name:'Review selected (1)'}));const help=within(header).getByRole('button',{name:'About review selection'});await act(()=>help.focus());await waitFor(()=>assert.match(baseScreen.getByRole('tooltip').textContent||'',/Each selected revision is reviewed separately/));await user.keyboard('{Escape}');await waitFor(()=>assert.equal(baseScreen.queryByRole('tooltip'),null));await user.click(within(header).getByRole('button',{name:'Review selected (1)'}));assert.match(window.location.hash,/review\/en\/rev-10000/)});

test('Demo login validates credentials, restores the session, signs out and guards role routes',async()=>{sessionStorage.clear();window.history.replaceState(null,'','/#/admin/members');const user=userEvent.setup();render(<App/>);assert.ok(baseScreen.getByRole('heading',{name:'Sign in to your workspace'}));assert.equal(document.querySelector('.ag-root-wrapper'),null);assert.equal(baseScreen.queryByRole('combobox',{name:'Actor role'}),null);await user.type(baseScreen.getByLabelText('Email',{exact:true}),'noor@example.org');await user.type(baseScreen.getByLabelText('Password',{exact:true}),'wrong');await user.click(baseScreen.getByRole('button',{name:'Sign in',exact:true}));assert.match(baseScreen.getByRole('alert').textContent||'',/Check your email/);await user.click(baseScreen.getByRole('button',{name:'Use Noor Haddad account'}));await user.click(baseScreen.getByRole('button',{name:'Sign in',exact:true}));await settleGrid();assert.ok(baseScreen.getByRole('heading',{name:'Members',exact:true}));assert.equal(sessionStorage.getItem('wikiwatch-demo-session'),'noor');assert.equal(baseScreen.queryByRole('button',{name:'Claim Board'}),null);await act(()=>{window.location.hash='#/review/en/rev-10000?role=patroller&user=dev';window.dispatchEvent(new Event('hashchange'))});assert.equal(baseScreen.queryByTestId('diff-viewer'),null);assert.ok(baseScreen.getByRole('heading',{name:'Edit Activity',exact:true}));assert.match(window.location.hash,/^#\/admin\/activity\?user=noor/);cleanup();render(<App/>);await settleGrid();assert.ok(baseScreen.getByRole('button',{name:'Sign out'}));await user.click(baseScreen.getByRole('button',{name:'Sign out'}));assert.equal(sessionStorage.getItem('wikiwatch-demo-session'),null);await act(()=>{window.location.hash='#/admin/members';window.dispatchEvent(new Event('hashchange'))});assert.ok(baseScreen.getByRole('heading',{name:'Sign in to your workspace'}));assert.equal(document.querySelector('.ag-root-wrapper'),null);await user.click(baseScreen.getByRole('button',{name:'Use Dev Patel account'}));await user.click(baseScreen.getByRole('button',{name:'Sign in',exact:true}));await settleGrid();assert.ok(baseScreen.getByRole('heading',{name:'Live feed',exact:true}));assert.equal(baseScreen.queryByRole('button',{name:'Members',exact:true}),null);assert.match(window.location.hash,/^#\/patroller\/feed\?user=dev/);await act(()=>{window.location.hash='#/patroller/claims?user=amir';window.dispatchEvent(new Event('hashchange'))});await settleGrid();assert.match(window.location.hash,/user=dev/);assert.ok(baseScreen.getByRole('heading',{name:'My Claims',exact:true}));await user.click(baseScreen.getByRole('button',{name:'Dev mode'}));assert.equal(baseScreen.queryByRole('combobox',{name:'Reviewer account'}),null);assert.equal(baseScreen.queryByRole('combobox',{name:'Workspace account'}),null)});

test('Route policy allows only the signed-in role and ignores URL account impersonation',async()=>{const {guardedRoute}=await import('../src/auth');const members=seed().members;for(const member of members){for(const [role,tab] of [['patroller','claims'],['lead','board'],['admin','members']]){const result=guardedRoute(member,`#/${role}/${tab}?user=someone-else`);assert.equal(result.route.role,member.role);assert.equal(result.route.user,member.id);assert.equal(result.denied,role!==member.role)}assert.equal(guardedRoute(member,'#/admin/claims').denied,true);assert.equal(guardedRoute(member,'#/patroller/members').denied,true);assert.equal(guardedRoute(member,'#/review/en/%E0%A4%A').denied,true)}const admin=members.find(m=>m.role==='admin')!;assert.equal(guardedRoute(admin,'#/review/en/rev-10000?role=admin').denied,true);const lead=members.find(m=>m.role==='lead')!;assert.equal(guardedRoute(lead,'#/review/en/rev-10000?role=lead&user=dev').route.user,lead.id)});

test('Inactive accounts cannot sign in and removing current access returns to login',async()=>{sessionStorage.clear();const state=seed();state.members=state.members.map(m=>m.id==='dev'?{...m,active:false}:m);localStorage.setItem(KEY,JSON.stringify(state));const user=userEvent.setup();render(<App/>);assert.equal(baseScreen.queryByRole('button',{name:'Use Dev Patel account'}),null);await user.type(baseScreen.getByLabelText('Email',{exact:true}),'dev@example.org');await user.type(baseScreen.getByLabelText('Password',{exact:true}),'demo123');await user.click(baseScreen.getByRole('button',{name:'Sign in',exact:true}));assert.ok(baseScreen.getByRole('alert'));await user.click(baseScreen.getByRole('button',{name:'Use Amir Reza account'}));await user.click(baseScreen.getByRole('button',{name:'Sign in',exact:true}));await settleGrid();assert.equal(sessionStorage.getItem('wikiwatch-demo-session'),'amir');const removed={...state,members:state.members.map(m=>m.id==='amir'?{...m,active:false}:m)};await act(()=>{localStorage.setItem(KEY,JSON.stringify(removed));window.dispatchEvent(new StorageEvent('storage',{key:KEY,newValue:JSON.stringify(removed)}))});assert.ok(baseScreen.getByRole('heading',{name:'Sign in to your workspace'}));assert.match(baseScreen.getByRole('alert').textContent||'',/access changed/);assert.equal(sessionStorage.getItem('wikiwatch-demo-session'),null);assert.equal(document.querySelector('.ag-root-wrapper'),null)});

test('Compact navigation opens allowed pages and exposes guide and developer tools',async()=>{const user=userEvent.setup();render(<App/>);await settleGrid();await user.click(baseScreen.getByRole('button',{name:'Open navigation'}));let dialog=baseScreen.getByRole('dialog',{name:'Workspace navigation'});assert.equal(within(dialog).queryByRole('button',{name:'Members',exact:true}),null);await user.click(within(dialog).getByRole('button',{name:'My Claims',exact:true}));assert.equal(baseScreen.queryByRole('dialog'),null);assert.ok(baseScreen.getByRole('heading',{name:'My Claims',exact:true}));await user.click(baseScreen.getByRole('button',{name:'Open navigation'}));dialog=baseScreen.getByRole('dialog',{name:'Workspace navigation'});await user.click(within(dialog).getByRole('button',{name:'Dev mode',exact:true}));assert.ok(baseScreen.getByRole('dialog',{name:'Dev mode'}));await user.keyboard('{Escape}');await user.click(baseScreen.getByRole('button',{name:'Open navigation'}));dialog=baseScreen.getByRole('dialog',{name:'Workspace navigation'});await user.click(within(dialog).getByRole('button',{name:'Guide',exact:true}));assert.ok(baseScreen.getByRole('dialog',{name:'Workspace guide'}));});
